// Type-safe multiplatform navigation — org.jetbrains.androidx.navigation:navigation-compose
@Serializable object Home
@Serializable data class Profile(val id: Long)

@Composable
fun App() {
  val nav = rememberNavController()
  NavHost(nav, startDestination = Home) {
    composable<Home> { HomeScreen(onProfile = { id -> nav.navigate(Profile(id)) }) }
    composable<Profile> { entry ->
      ProfileScreen(id = entry.toRoute<Profile>().id, onBack = { nav.popBackStack() })
    }
  }
}

