@Composable
fun HomeScaffold(content: @Composable () -> Unit) {
  val info = currentWindowAdaptiveInfo()
  val wide = info.windowSizeClass.windowWidthSizeClass != WindowWidthSizeClass.COMPACT

  Scaffold(
    contentWindowInsets = WindowInsets.safeDrawing,   // notch, home indicator, system bars
    bottomBar = { if (!wide) BottomBar() }
  ) { padding ->
    Row(Modifier.padding(padding)) {
      if (wide) NavigationRail { RailItems() }        // tablet / desktop
      Box(Modifier.weight(1f).imePadding()) { content() }
    }
  }
}

