// Proof that the runtime is not a UI toolkit: compose a plain tree, no compose.ui at all.
class Node(val name: String) {
  val children = mutableListOf<Node>()
}

class NodeApplier(root: Node) : AbstractApplier<Node>(root) {
  override fun insertTopDown(index: Int, instance: Node) { /* bottom-up is cheaper here */ }
  override fun insertBottomUp(index: Int, instance: Node) { current.children.add(index, instance) }
  override fun remove(index: Int, count: Int) { current.children.remove(index, count) }
  override fun move(from: Int, to: Int, count: Int) { current.children.move(from, to, count) }
  override fun onClear() { root.children.clear() }
}

@Composable
fun Branch(name: String, content: @Composable () -> Unit = {}) {
  ComposeNode<Node, NodeApplier>(factory = { Node(name) }, update = {}, content = content)
}

