// ❌ Registers with the platform, never unregisters — and hands a UIView to a Kotlin singleton
@Composable
fun MapPanel(state: MapState) {
  UIKitView(factory = {
    MKMapView().apply {
      setDelegate(MapDelegate(state))   // UIKit retains a Kotlin object...
      AppRouter.mapView = this          // ...and Kotlin retains the UIKit object: immortal
    }
  })
  CoroutineScope(Dispatchers.Main).launch { state.follow() }   // never cancelled
}

// ✅ The composition owns both the registration and the release
@Composable
fun MapPanel(state: MapState) {
  val scope = rememberCoroutineScope()             // cancelled when the node leaves
  val delegate = remember { MapDelegate(state) }

  UIKitView(
    factory = { MKMapView().apply { setDelegate(delegate) } },
    modifier = Modifier.fillMaxSize()
  )

  DisposableEffect(Unit) {
    val token = NSNotificationCenter.defaultCenter.addObserverForName(
      name = "LocationChanged",
      `object` = null,
      queue = null
    ) { _ -> scope.launch { state.refresh() } }
    onDispose { NSNotificationCenter.defaultCenter.removeObserver(token) }
  }
}

